class Solution {
    int best = 0;

    pair<int, int> dfs(TreeNode* node) {
        if (!node) {
            return {0, 0};
        }
        int increasing = 1, decreasing = 1;
        if (node->left) {
            auto lengths = dfs(node->left);
            if (node->left->val == node->val + 1) {
                increasing = max(increasing, lengths.first + 1);
            }
            if (node->left->val == node->val - 1) {
                decreasing = max(decreasing, lengths.second + 1);
            }
        }
        if (node->right) {
            auto lengths = dfs(node->right);
            if (node->right->val == node->val + 1) {
                increasing = max(increasing, lengths.first + 1);
            }
            if (node->right->val == node->val - 1) {
                decreasing = max(decreasing, lengths.second + 1);
            }
        }
        best = max(best, increasing + decreasing - 1);
        return {increasing, decreasing};
    }

public:
    int longestConsecutive(TreeNode* root) {
        best = 0;
        dfs(root);
        return best;
    }
};
